  N.tips = {
    va1l1: [m('«Por lo visto» = me lo han contado. «Encima» = y además, ¡qué rabia!', '“Por lo visto” = I’ve been told. “Encima” = and on top of that, how annoying!'), m('No abuses de «o sea». Prueba con «vamos» o «es decir».', 'Don’t overuse “o sea”. Try “vamos” or “es decir”.')],
    va1l2: [m('Un comentario no resume: explica cómo la forma crea el sentido.', 'A commentary doesn’t summarise: it explains how form creates meaning.'), m('Con «como» es símil; sin «como», metáfora.', 'With “como” it’s a simile; without it, a metaphor.')],
    va1l3: [m('El gerundio no sirve para «y después». Se cayó y se rompió, no «rompiéndose».', 'The gerund doesn’t mean “and then”. Se cayó y se rompió, not “rompiéndose”.'), m('«Apenas hubo terminado» suena a novela. ¡Reconócelo, no hace falta decirlo!', '“Apenas hubo terminado” sounds like a novel. Recognise it — no need to say it!')],
    va2l1: [m('Lo bueno, lo malo, lo curioso… «lo» convierte cualquier adjetivo en una idea.', 'Lo bueno, lo malo, lo curioso… “lo” turns any adjective into an idea.'), m('Ojo: «lo cansadas que estaban» — el adjetivo concuerda.', 'Careful: “lo cansadas que estaban” — the adjective agrees.')],
    va2l2: [m('Di al público adónde vas: en primer lugar, a continuación, por último.', 'Tell the audience where you’re going: first, next, finally.'), m('Si no sabes una respuesta, sé elegante: «No dispongo de ese dato ahora mismo».', 'If you don’t know an answer, be elegant: “No dispongo de ese dato ahora mismo”.')],
    va2l3: [m('Grosso modo, sin «a». Y statu quo, sin «s».', 'Grosso modo, without “a”. And statu quo, without “s”.'), m('Un trámite kafkiano, un proyecto quijotesco: la literatura vive en la calle.', 'A Kafkaesque procedure, a quixotic project: literature lives in the street.')]
  };
